ALTER TABLE payroll_runs DROP CONSTRAINT IF EXISTS payroll_runs_status_check;
ALTER TABLE payroll_runs ALTER COLUMN status SET DEFAULT 'awaiting_hr';
UPDATE payroll_runs SET status='awaiting_hr' WHERE status='pending_ceo_approval';
ALTER TABLE payroll_runs ADD CONSTRAINT payroll_runs_status_check CHECK(status IN ('awaiting_hr','awaiting_finance','awaiting_management','awaiting_ceo','approved','rejected'));
CREATE TABLE IF NOT EXISTS payroll_approval_roles (employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE, approver_id UUID NOT NULL REFERENCES employer_accounts(id), role TEXT NOT NULL CHECK(role IN ('hr','finance','management')), PRIMARY KEY(employer_id,role), UNIQUE(employer_id,approver_id));
CREATE TABLE IF NOT EXISTS payroll_approval_decisions (id UUID PRIMARY KEY, payroll_run_id UUID NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, approver_id UUID NOT NULL REFERENCES employer_accounts(id), stage TEXT NOT NULL CHECK(stage IN ('hr','finance','management','ceo')), decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), note TEXT, decided_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(payroll_run_id,stage));
CREATE OR REPLACE VIEW payable_payroll_runs AS SELECT r.* FROM payroll_runs r WHERE r.status='approved' AND (SELECT COUNT(*) FROM payroll_approval_decisions d WHERE d.payroll_run_id=r.id AND d.decision='approved')=4;
CREATE TABLE IF NOT EXISTS employee_confirmations (id UUID PRIMARY KEY, employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE, employee_id UUID NOT NULL REFERENCES payroll_employees(id) ON DELETE CASCADE, start_date DATE NOT NULL, probation_months INT NOT NULL CHECK(probation_months IN (3,6)), due_date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','extended')), review_notes TEXT, reviewed_at TIMESTAMPTZ, UNIQUE(employer_id,employee_id));
